var n=`1188-tres-leches-cake`;var t=`world-1188`;var r=`MX`;var a=`central-america-caribbean`;var s=8;var o=240;var l={en:`Tres Leches Cake`,ua:`Торт «Три молока»`};var d={en:`Tres Leches Cake is a dish from Mexico prepared with all-purpose flour, chicken egg, whole cow milk, baking powder. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Торт «Три молока», страва кухні країни Мексика, яку готують із таких продуктів: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко, розпушувач тіста. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:13,i:[[`all-purpose-flour`,330,`g`],[`chicken-egg`,5,`pcs`],[`white-granulated-sugar`,180,`g`],[`whole-cow-milk`,230,`ml`],[`baking-powder`,12,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 30 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 30 хвилин до готовності.`,t:[`baking`],m:30,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`evaporated-milk`,380,`ml`],[`sweetened-condensed-milk`,400,`g`],[`whole-cow-milk`,300,`ml`]]},{en:`Arrange the already cooked and prepared components for serving, keeping hot and cold components at their safe temperatures.`,ua:`Зберіть раніше приготовані компоненти для подавання, підтримуючи безпечну температуру гарячого й холодного.`,t:[`layered-assembly`,`garnishing`],m:7,i:[]},{en:`Refrigerate the prepared mixture for about 180 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 180 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:180,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`whipping-cream`,180,`ml`]]}];var m={slug:n,id:t,country:`MX`,region:a,servings:8,minutes:240,title:l,text:d,steps:h};export{r as country,m as default,t as id,o as minutes,a as region,s as servings,n as slug,h as steps,d as text,l as title};